  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "GSK931145, an amide-containing basic small molecule, showed good brain penetration in pig PET, supporting that the query's amide and secondary amine can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "LY450108, a fluorophenyl amide-like compound, had quantifiable CSF concentrations in healthy humans, demonstrating meaningful CNS access for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Diphenyl acrylonitrile 32b, containing a nitrile and amide, showed a brain-to-plasma ratio of 1.59 in rats, supporting that the query's nitrile-amide motif can penetrate the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Excitin-1, a leucine conjugate, was detected in multiple brain regions after oral administration, supporting that the query's leucine-like isobutyl side chain does not prevent brain uptake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Benztropine analogs with basic nitrogen and lipophilic aryl groups readily crossed the BBB with high brain-to-plasma ratios, supporting the query's basic amine and fluorophenyl.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, lipophilic molecule with a basic amine, amide, nitrile, and fluorophenyl/trifluoromethyl groups. All ten analogues demonstrate positive BBB/CNS penetration, including compounds with similar amide, nitrile, and basic amine motifs. The evidence strongly supports meaningful CNS access.",
